"""Extract exact old assertion AST blocks, never import old executing modules."""
import argparse,ast,hashlib,json,pathlib
P=pathlib.Path(__file__).resolve().parent

def main():
 p=argparse.ArgumentParser();p.add_argument('--old-preparation',type=pathlib.Path,required=True);p.add_argument('--contract',type=pathlib.Path,required=True);a=p.parse_args();contract=json.loads(a.contract.read_text());proof=[]
 specs=[('watch-browser-contract-848-browser-20261020.py','group37_predicates.py',15,26),('review-browser-contract-848-targeted-20261020.py','group7_predicates.py',9,49)]
 for name,out,lo,hi in specs:
  source=a.old_preparation/name;raw=source.read_bytes();expected=contract['current_reader_and_host_envelope_sha256'][str(source)];assert hashlib.sha256(raw).hexdigest()==expected;tree=ast.parse(raw);original=next(n for n in tree.body if isinstance(n,ast.Try)).body[lo:hi];assert isinstance(original[0],ast.For) and any(isinstance(n,ast.Assert) for n in original)
  function=ast.FunctionDef(name='review',args=ast.arguments(posonlyargs=[],args=[ast.arg(arg=n) for n in ['e','design','binding','S','B','O']],kwonlyargs=[],kw_defaults=[],defaults=[]),body=original+[ast.Return(value=ast.Name(id='report',ctx=ast.Load()))],decorator_list=[])
  module=ast.Module(body=[ast.Import(names=[ast.alias(name='hashlib'),ast.alias(name='json'),ast.alias(name='pathlib')]),ast.Assign(targets=[ast.Name(id='sha',ctx=ast.Store())],value=ast.Lambda(args=ast.arguments(posonlyargs=[],args=[ast.arg(arg='b')],kwonlyargs=[],kw_defaults=[],defaults=[]),body=ast.Call(func=ast.Attribute(value=ast.Call(func=ast.Attribute(value=ast.Name(id='hashlib',ctx=ast.Load()),attr='sha256',ctx=ast.Load()),args=[ast.Name(id='b',ctx=ast.Load())],keywords=[]),attr='hexdigest',ctx=ast.Load()),args=[],keywords=[]))),function],type_ignores=[]);ast.fix_missing_locations(module);text='"""Frozen original assertions; extracted unchanged, no dispatch/engine code."""\n'+ast.unparse(module)+'\n';target=P/out;target.write_text(text);newfn=next(n for n in ast.parse(text).body if isinstance(n,ast.FunctionDef));newbody=newfn.body[:-1];old_ast=ast.dump(ast.Module(body=original,type_ignores=[]),include_attributes=False);new_ast=ast.dump(ast.Module(body=newbody,type_ignores=[]),include_attributes=False);assert old_ast==new_ast
  proof.append({'old_reader_name':name,'old_reader_sha256':expected,'original_try_statement_slice':[lo,hi],'old_block_first_line':original[0].lineno,'old_block_last_line':original[-1].end_lineno,'new_module':out,'new_module_sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'assertion_block_AST_sha256':hashlib.sha256(old_ast.encode()).hexdigest(),'exact_original_block_AST_equal':True,'original_top_level_statement_count':len(original),'all_asserts_recursive':sum(isinstance(n,ast.Assert) for x in original for n in ast.walk(x)),'excluded':'old resource/readiness polling, collector/provider/dispatch, receipt writes and old hardcoded-source admission; replaced by explicit authenticated grouped saved envelope only'})
 (P/'AST-EQUALITY-PROOF.json').write_text(json.dumps({'status':'EXTRACTION_ONLY_NOT_EXECUTED_ON_ACTUAL_REPORT','blocks':proof},indent=2)+'\n')
